/* Pastel Dreams Theme — Tailwind v3 (hex) */
/* Channel triplets — consume via rgb(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Pastel Dreams Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 248 243 250;
    --foreground: 54 64 80;
    --card: 255 255 255;
    --card-foreground: 54 64 80;
    --popover: 255 255 255;
    --popover-foreground: 54 64 80;
    --primary: 167 139 251;
    --primary-foreground: 255 255 255;
    --secondary: 233 217 252;
    --secondary-foreground: 75 86 102;
    --muted: 244 234 255;
    --muted-foreground: 108 114 126;
    --accent: 245 229 247;
    --accent-foreground: 54 64 80;
    --destructive: 251 167 167;
    --destructive-foreground: 255 255 255;
    --border: 233 217 252;
    --input: 233 217 252;
    --ring: 167 139 251;
    --chart-1: 167 139 251;
    --chart-2: 140 93 248;
    --chart-3: 124 56 238;
    --chart-4: 109 41 216;
    --chart-5: 90 32 181;
    --radius: 1.5rem;
    --sidebar: 233 217 252;
    --sidebar-foreground: 54 64 80;
    --sidebar-primary: 167 139 251;
    --sidebar-primary-foreground: 255 255 255;
    --sidebar-accent: 245 229 247;
    --sidebar-accent-foreground: 54 64 80;
    --sidebar-border: 233 217 252;
    --sidebar-ring: 167 139 251;
    --font-sans: Open Sans, sans-serif;
    --font-serif: Source Serif 4, serif;
    --font-mono: IBM Plex Mono, monospace;
    --shadow-color: 0 0 0;
    --shadow-opacity: 0.08;
    --shadow-blur: 16px;
    --shadow-spread: -4px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 8px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 8px 16px -4px hsl(0 0% 0% / 0.04);
    --shadow-xs: 0px 8px 16px -4px hsl(0 0% 0% / 0.04);
    --shadow-sm:
      0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 1px 2px -5px hsl(0 0% 0% / 0.08);
    --shadow:
      0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 1px 2px -5px hsl(0 0% 0% / 0.08);
    --shadow-md:
      0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 2px 4px -5px hsl(0 0% 0% / 0.08);
    --shadow-lg:
      0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 4px 6px -5px hsl(0 0% 0% / 0.08);
    --shadow-xl:
      0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 8px 10px -5px hsl(0 0% 0% / 0.08);
    --shadow-2xl: 0px 8px 16px -4px hsl(0 0% 0% / 0.2);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 30 25 22;
    --foreground: 225 231 253;
    --card: 45 37 53;
    --card-foreground: 225 231 253;
    --popover: 45 37 53;
    --popover-foreground: 225 231 253;
    --primary: 193 170 255;
    --primary-foreground: 30 25 22;
    --secondary: 62 50 72;
    --secondary-foreground: 208 212 219;
    --muted: 45 37 53;
    --muted-foreground: 155 162 174;
    --accent: 75 62 91;
    --accent-foreground: 208 212 219;
    --destructive: 251 167 167;
    --destructive-foreground: 30 25 22;
    --border: 62 50 72;
    --input: 62 50 72;
    --ring: 193 170 255;
    --chart-1: 193 170 255;
    --chart-2: 167 139 251;
    --chart-3: 140 93 248;
    --chart-4: 124 56 238;
    --chart-5: 109 41 216;
    --radius: 1.5rem;
    --sidebar: 62 50 72;
    --sidebar-foreground: 225 231 253;
    --sidebar-primary: 193 170 255;
    --sidebar-primary-foreground: 30 25 22;
    --sidebar-accent: 75 62 91;
    --sidebar-accent-foreground: 208 212 219;
    --sidebar-border: 62 50 72;
    --sidebar-ring: 193 170 255;
    --font-sans: Open Sans, sans-serif;
    --font-serif: Source Serif 4, serif;
    --font-mono: IBM Plex Mono, monospace;
    --shadow-color: 0 0 0;
    --shadow-opacity: 0.08;
    --shadow-blur: 16px;
    --shadow-spread: -4px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 8px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 8px 16px -4px hsl(0 0% 0% / 0.04);
    --shadow-xs: 0px 8px 16px -4px hsl(0 0% 0% / 0.04);
    --shadow-sm:
      0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 1px 2px -5px hsl(0 0% 0% / 0.08);
    --shadow:
      0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 1px 2px -5px hsl(0 0% 0% / 0.08);
    --shadow-md:
      0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 2px 4px -5px hsl(0 0% 0% / 0.08);
    --shadow-lg:
      0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 4px 6px -5px hsl(0 0% 0% / 0.08);
    --shadow-xl:
      0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 8px 10px -5px hsl(0 0% 0% / 0.08);
    --shadow-2xl: 0px 8px 16px -4px hsl(0 0% 0% / 0.2);
  }

}
